-- New System: all writes to official stock go through post_operation().
CREATE TABLE businesses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Jakarta', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, name text NOT NULL, UNIQUE(business_id,id));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE permissions(role text PRIMARY KEY, actions text[] NOT NULL);
INSERT INTO permissions VALUES ('owner',ARRAY['read','catalog','purchase','receive','sell','pay','adjust','settings']),('manager',ARRAY['read','catalog','purchase','receive','sell','pay','adjust']),('cashier',ARRAY['read','sell']),('warehouse',ARRAY['read','receive']);
CREATE TABLE business_memberships(business_id uuid NOT NULL REFERENCES businesses,user_id uuid NOT NULL REFERENCES users,role text NOT NULL REFERENCES permissions,PRIMARY KEY(business_id,user_id));
CREATE TABLE login_attempts(key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,name text NOT NULL,UNIQUE(business_id,name));
CREATE TABLE product_units(code text PRIMARY KEY,label text NOT NULL);
INSERT INTO product_units SELECT u,u FROM unnest(ARRAY['PCS','SET','TIN','DOS','DUS','BOTOL','LSN','M','DRM','PACK','BOX','KARTON','KG','GRAM','LITER','SACHET']) u;
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,name text NOT NULL,contact text,whatsapp text,address text,payment_days integer NOT NULL DEFAULT 0 CHECK(payment_days>=0),lead_days integer NOT NULL DEFAULT 7 CHECK(lead_days>=0),active boolean NOT NULL DEFAULT true,UNIQUE(business_id,name),UNIQUE(business_id,id));
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,sku text NOT NULL,barcode text,name text NOT NULL,category_id uuid REFERENCES product_categories,brand text,base_unit text NOT NULL REFERENCES product_units,purchase_cost numeric(20,2) NOT NULL DEFAULT 0 CHECK(purchase_cost>=0),selling_price numeric(20,2) CHECK(selling_price>=0),min_stock numeric(20,4) NOT NULL DEFAULT 0 CHECK(min_stock>=0),photo_url text,active boolean NOT NULL DEFAULT true,stock_verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(business_id,sku),UNIQUE(business_id,id));
CREATE UNIQUE INDEX products_barcode ON products(business_id,barcode) WHERE barcode IS NOT NULL AND barcode<>'';
CREATE INDEX products_lookup ON products(business_id,lower(name));
CREATE TABLE product_unit_conversions(business_id uuid NOT NULL REFERENCES businesses,product_id uuid NOT NULL,unit text NOT NULL REFERENCES product_units,multiplier numeric(20,6) NOT NULL CHECK(multiplier>0),PRIMARY KEY(business_id,product_id,unit),FOREIGN KEY(business_id,product_id) REFERENCES products(business_id,id));
CREATE TABLE product_supplier_mappings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,product_id uuid NOT NULL,supplier_id uuid NOT NULL,supplier_code text NOT NULL,alias text,confirmed_by uuid REFERENCES users,FOREIGN KEY(business_id,product_id) REFERENCES products(business_id,id),FOREIGN KEY(business_id,supplier_id) REFERENCES suppliers(business_id,id),UNIQUE(business_id,supplier_id,supplier_code));
CREATE TABLE supplier_price_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,business_id uuid NOT NULL REFERENCES businesses,product_id uuid NOT NULL,supplier_id uuid NOT NULL,unit_cost numeric(20,2) NOT NULL CHECK(unit_cost>=0),observed_at timestamptz NOT NULL DEFAULT now(),reference text NOT NULL,FOREIGN KEY(business_id,product_id) REFERENCES products(business_id,id),FOREIGN KEY(business_id,supplier_id) REFERENCES suppliers(business_id,id));
CREATE INDEX supplier_prices_lookup ON supplier_price_history(business_id,product_id,supplier_id,observed_at DESC);
CREATE TABLE scanned_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,content_hash text NOT NULL,filename text NOT NULL,storage_mode text NOT NULL DEFAULT 'local-only',object_key text,created_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(business_id,content_hash));
CREATE TABLE ocr_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES scanned_documents,status text NOT NULL CHECK(status IN ('pending','running','review','cancelled','failed','confirmed')),engine_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ocr_raw_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES ocr_jobs,raw_text text NOT NULL,positional_evidence jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ocr_parsed_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES ocr_jobs,line_index integer NOT NULL,data jsonb NOT NULL,warnings jsonb NOT NULL DEFAULT '[]',UNIQUE(job_id,line_index));
CREATE TABLE ocr_review_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,document_id uuid REFERENCES scanned_documents,mode text NOT NULL CHECK(mode IN ('PURCHASE_RECEIPT','OPENING_BALANCE')),data jsonb NOT NULL,version integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'draft',created_by uuid REFERENCES users,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,supplier_id uuid NOT NULL,reference text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','partial','received','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(business_id,supplier_id) REFERENCES suppliers(business_id,id),UNIQUE(business_id,reference),UNIQUE(business_id,id));
CREATE TABLE purchase_order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,order_id uuid NOT NULL,product_id uuid NOT NULL,quantity numeric(20,4) NOT NULL CHECK(quantity>0),received_quantity numeric(20,4) NOT NULL DEFAULT 0 CHECK(received_quantity>=0),unit text NOT NULL REFERENCES product_units,unit_price numeric(20,2) NOT NULL CHECK(unit_price>=0),FOREIGN KEY(business_id,order_id) REFERENCES purchase_orders(business_id,id),FOREIGN KEY(business_id,product_id) REFERENCES products(business_id,id),UNIQUE(order_id,product_id));
CREATE TABLE operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,location_id uuid NOT NULL,type text NOT NULL CHECK(type IN ('OPENING_BALANCE','PURCHASE_RECEIPT','SALE','CUSTOMER_RETURN','SUPPLIER_RETURN','STOCK_ADJUSTMENT','DAMAGE','TRANSFER_IN','TRANSFER_OUT','TRANSFER','PAYMENT')),idempotency_key text NOT NULL,payload_hash text NOT NULL,reference text NOT NULL,payload jsonb NOT NULL,created_by uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(business_id,location_id) REFERENCES locations(business_id,id),UNIQUE(business_id,idempotency_key),UNIQUE(business_id,id));
CREATE TABLE inventory_movements(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,business_id uuid NOT NULL REFERENCES businesses,location_id uuid NOT NULL,product_id uuid NOT NULL,operation_id uuid NOT NULL,type text NOT NULL,quantity numeric(20,4) NOT NULL CHECK(quantity<>0),unit_cost numeric(20,2) NOT NULL CHECK(unit_cost>=0),reference text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(business_id,location_id) REFERENCES locations(business_id,id),FOREIGN KEY(business_id,product_id) REFERENCES products(business_id,id),FOREIGN KEY(business_id,operation_id) REFERENCES operations(business_id,id));
CREATE INDEX movement_product_time ON inventory_movements(business_id,product_id,created_at DESC);
CREATE TABLE inventory_balances(business_id uuid NOT NULL REFERENCES businesses,location_id uuid NOT NULL,product_id uuid NOT NULL,quantity numeric(20,4) NOT NULL DEFAULT 0 CHECK(quantity>=0),average_cost numeric(20,2) NOT NULL DEFAULT 0 CHECK(average_cost>=0),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(business_id,location_id,product_id),FOREIGN KEY(business_id,location_id) REFERENCES locations(business_id,id),FOREIGN KEY(business_id,product_id) REFERENCES products(business_id,id));
CREATE TABLE goods_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,operation_id uuid NOT NULL UNIQUE REFERENCES operations,supplier_id uuid NOT NULL,order_id uuid,invoice_date date NOT NULL,delivery_date date,received_at timestamptz NOT NULL DEFAULT now(),discrepancies jsonb NOT NULL DEFAULT '[]',FOREIGN KEY(business_id,supplier_id) REFERENCES suppliers(business_id,id),FOREIGN KEY(business_id,order_id) REFERENCES purchase_orders(business_id,id));
CREATE TABLE goods_receipt_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),receipt_id uuid NOT NULL REFERENCES goods_receipts,product_id uuid NOT NULL REFERENCES products,invoice_quantity numeric(20,4) NOT NULL CHECK(invoice_quantity>=0),received_quantity numeric(20,4) NOT NULL CHECK(received_quantity>=0),damaged_quantity numeric(20,4) NOT NULL DEFAULT 0 CHECK(damaged_quantity>=0),unit text NOT NULL,multiplier numeric(20,6) NOT NULL CHECK(multiplier>0),unit_price numeric(20,2) NOT NULL CHECK(unit_price>=0),discount numeric(20,2) NOT NULL DEFAULT 0,tax numeric(20,2) NOT NULL DEFAULT 0);
CREATE TABLE supplier_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,supplier_id uuid NOT NULL,operation_id uuid NOT NULL UNIQUE REFERENCES operations,receipt_id uuid REFERENCES goods_receipts,invoice_number text NOT NULL,invoice_date date NOT NULL,delivery_date date,due_date date,subtotal numeric(20,2) NOT NULL,total numeric(20,2) NOT NULL CHECK(total>=0),paid_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK(paid_amount>=0 AND paid_amount<=total),status text NOT NULL CHECK(status IN ('blocked','approved','paid')),match_warnings jsonb NOT NULL DEFAULT '[]',FOREIGN KEY(business_id,supplier_id) REFERENCES suppliers(business_id,id),UNIQUE(business_id,supplier_id,invoice_number),UNIQUE(business_id,id));
CREATE TABLE supplier_invoice_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL REFERENCES supplier_invoices,product_id uuid NOT NULL REFERENCES products,quantity numeric(20,4) NOT NULL,unit text NOT NULL,unit_price numeric(20,2) NOT NULL,discount numeric(20,2) NOT NULL DEFAULT 0,tax numeric(20,2) NOT NULL DEFAULT 0,line_total numeric(20,2) NOT NULL);
CREATE TABLE supplier_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,invoice_id uuid NOT NULL,operation_id uuid NOT NULL REFERENCES operations,amount numeric(20,2) NOT NULL CHECK(amount>0),method text NOT NULL CHECK(method IN ('cash','transfer','credit_note')),proof_reference text NOT NULL,paid_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(business_id,invoice_id) REFERENCES supplier_invoices(business_id,id));
CREATE TABLE sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,operation_id uuid NOT NULL UNIQUE REFERENCES operations,reference text NOT NULL,total numeric(20,2) NOT NULL CHECK(total>=0),discount numeric(20,2) NOT NULL DEFAULT 0,cost_total numeric(20,2) NOT NULL CHECK(cost_total>=0),payment_method text NOT NULL CHECK(payment_method IN ('cash','transfer')),tendered numeric(20,2) NOT NULL CHECK(tendered>=total),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sales_time ON sales(business_id,created_at DESC);
CREATE TABLE sales_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sale_id uuid NOT NULL REFERENCES sales,product_id uuid NOT NULL REFERENCES products,quantity numeric(20,4) NOT NULL CHECK(quantity>0),unit_price numeric(20,2) NOT NULL CHECK(unit_price>=0),unit_cost numeric(20,2) NOT NULL CHECK(unit_cost>=0),line_total numeric(20,2) NOT NULL);
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,business_id uuid NOT NULL REFERENCES businesses,actor_id uuid REFERENCES users,action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_scope ON audit_logs(business_id,created_at DESC);
CREATE TABLE source_imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,source_id text NOT NULL,source_hash text NOT NULL,source_title text NOT NULL,report jsonb NOT NULL,imported_at timestamptz NOT NULL DEFAULT now(),UNIQUE(business_id,source_hash));
CREATE TABLE source_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,import_id uuid NOT NULL REFERENCES source_imports,sheet text NOT NULL,row_number integer NOT NULL,data jsonb NOT NULL,status text NOT NULL DEFAULT 'unverified',UNIQUE(import_id,sheet,row_number));
CREATE TABLE tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,entity_type text NOT NULL,entity_id text NOT NULL,tag text NOT NULL,source text NOT NULL CHECK(source IN ('rule','manual')),rule_version text,evidence jsonb NOT NULL,created_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(business_id,entity_type,entity_id,tag,source));
CREATE TABLE insight_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES businesses,rule_version text NOT NULL,insights jsonb NOT NULL,created_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());

CREATE FUNCTION prevent_history_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Riwayat tidak dapat diubah. Buat transaksi koreksi baru.'; END $$;
CREATE TRIGGER immutable_movements BEFORE UPDATE OR DELETE ON inventory_movements FOR EACH ROW EXECUTE FUNCTION prevent_history_change();
CREATE TRIGGER immutable_operations BEFORE UPDATE OR DELETE ON operations FOR EACH ROW EXECUTE FUNCTION prevent_history_change();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION prevent_history_change();
CREATE TRIGGER immutable_payments BEFORE UPDATE OR DELETE ON supplier_payments FOR EACH ROW EXECUTE FUNCTION prevent_history_change();
